**1. 캡슐화 (Encapsulation)**
```python
class BankAccount:
    def __init__(self, owner, initial_balance=0):
        self.owner = owner
        self.__balance = initial_balance  # private 변수

    def deposit(self, amount):
        if amount > 0:
            self.__balance += amount

    def get_balance(self):
        return self.__balance  # 안전한 접근 방법

# account.__balance로 직접 접근 불가 → 캡슐화
```

**2. 상속 (Inheritance)**
```python
class Account:  # 부모 클래스
    def __init__(self, owner, balance=0):
        self.owner = owner
        self.balance = balance

    def deposit(self, amount):
        self.balance += amount

class SavingsAccount(Account):  # 자식 클래스
    def __init__(self, owner, balance=0, interest_rate=0.02):
        super().__init__(owner, balance)  # 부모 특성 상속
        self.interest_rate = interest_rate

    def add_interest(self):  # 새로운 기능 추가
        self.balance *= (1 + self.interest_rate)
```

**3. 다형성 (Polymorphism)**
```python
class CheckingAccount(Account):
    def withdraw(self, amount):
        if self.balance >= amount:
            self.balance -= amount
            return f"출금: {amount}원"
        return "잔액 부족"

class SavingsAccount(Account):
    def withdraw(self, amount):
        fee = 1000
        total = amount + fee
        if self.balance >= total:
            self.balance -= total
            return f"출금: {amount}원 (수수료: {fee}원)"
        return "잔액 부족"

# 같은 withdraw 메서드지만 계좌 타입에 따라 다르게 동작
accounts = [CheckingAccount("태수", 50000), SavingsAccount("태수", 50000)]
for account in accounts:
    print(account.withdraw(10000))  # 다형성 구현
```

**4. 추상화 (Abstraction)**
```python
from abc import ABC, abstractmethod

class PaymentMethod(ABC):  # 추상 클래스
    @abstractmethod
    def process_payment(self, amount):
        pass  # 구현 세부사항은 숨기고 인터페이스만 정의

class CreditCard(PaymentMethod):
    def process_payment(self, amount):
        return f"신용카드로 {amount}원 결제 완료"

class BankTransfer(PaymentMethod):
    def process_payment(self, amount):
        return f"계좌이체로 {amount}원 결제 완료"

# 사용자는 복잡한 결제 로직을 몰라도 됨
```

